import { createHash } from 'node:crypto';

export const reportingPrompt = '请先阅读 .taskboard/REPORTING.md、.taskboard/CONTEXT.md 和 .taskboard/tasks.json。按已确认的需求拆分任务；开工、有进展、受阻和结束时，用通俗语言汇报已完成内容、剩余内容和下一步，并检查每次回执。不要虚造检查任务或结果。';

export const legacyReportingInstructions = `# 序程文件汇报说明

<!-- Generated by Seqivo file reporting -->
本文件由序程生成。遵循用户要求及项目已有 AGENTS.md、CLAUDE.md 等规则，不修改这些文件。先读 .taskboard/CONTEXT.md 和 .taskboard/tasks.json，核对已有任务，避免重复创建。文件缺失时告知用户检查目录绑定，不要伪造数据。

开工、取得进展、受阻和结束时，简要记录已完成内容、未完成内容和下一步。不要记录密码、令牌、私钥或完整私密对话。

每次事件写入 .taskboard/inbox/<事件ID>.tmp，写完后在同目录重命名为 <事件ID>.json。每次新事件使用新 UUID；仅重试完全相同的事件可沿用 eventId，同一个 ID 不得用于不同内容。不要直接修改 .taskboard/tasks.json、.taskboard/CONTEXT.md 或数据库。

新增任务（初始状态为 planned）：

\`\`\`json
{"eventId":"新UUID","type":"task.create","payload":{"title":"任务标题","goal":"目标","example":"具体示例","summary":"尚未开始","criteria":["验收条件"]}}
\`\`\`

先从最新 .taskboard/tasks.json 或成功回执取得真实 taskId 和 revision；后续每次提交都使用当前 expectedRevision：

\`\`\`json
{"eventId":"新UUID","type":"task.update","taskId":"真实任务ID","expectedRevision":1,"payload":{"status":"running","summary":"已完成内容","approach":"实现方式","nextStep":"下一步"}}
\`\`\`

允许更新 summary、approach、nextStep、status、implementationRef、blockedReason、sourceConversation。状态使用 planned、running、blocked、failed、submitted；受阻时填写 blockedReason。不得覆盖用户的暂停或取消决定；修改目标、验收条件和执行会话绑定由用户在看板确认。

交付时先更新为 submitted，再读取最新修订并提交真实证据：

\`\`\`json
{"eventId":"新UUID","type":"evidence.add","taskId":"真实任务ID","expectedRevision":2,"payload":{"summary":"实际验证内容和范围","reference":"实际存在的报告或产物路径"}}
\`\`\`

需要用户决策时使用：

\`\`\`json
{"eventId":"新UUID","type":"decision.request","taskId":"真实任务ID","expectedRevision":3,"payload":{"requestId":"新UUID","title":"需要决定的问题","summary":"背景","impact":"影响","options":[{"id":"option1","label":"方案一","consequence":"方案后果"}],"shareWithRemote":false}}
\`\`\`

每次等待 .taskboard/receipts/ 的回执，以 eventId 核对。accepted 返回 taskId、revision；rejected 的 error 说明原因。回执文件名是事件相对路径（例如 /inbox/事件ID.json）的 UTF-8 base64url 编码加 .json。修订冲突时重新读取快照并比较，再用新 eventId 提交；回执未到时保留原事件核查，避免重复创建任务。收到回执后确认快照与预期一致。

证据和 submitted 不代表人工验收通过；人工验收由用户完成。文件汇报不会自动启动、暂停或继续外部 AI。
`;

export const reportingMarker = '<!-- Generated by Seqivo file reporting -->';
export const reportingVersion = 2;
export const reportingInstructions = legacyReportingInstructions.replace(reportingMarker,
  `<!-- Seqivo file reporting v${reportingVersion} sha256:${createHash('sha256').update(legacyReportingInstructions).digest('hex')} -->`);

export const reportingRuleBlock = `<!-- Seqivo reporting rule: begin -->
Read .taskboard/REPORTING.md, .taskboard/CONTEXT.md and .taskboard/tasks.json before reporting work to Seqivo. Follow existing project rules and user instructions. Report only actual progress, blockers and verification through .taskboard/inbox events, then check .taskboard/receipts. Do not invent tasks or test results.
<!-- Seqivo reporting rule: end -->`;
